/* Home, the game page and a store page run their artwork under the strip.
   enhance.js marks the document once one of them is scrolled, and the strip
   gets a ground so passing text does not collide with the search field. */
#topbar::before {
  content: ''; position: absolute; inset: 0 0 -26px 0; z-index: -1; pointer-events: none;
  background: linear-gradient(180deg, var(--ground) 0%, color-mix(in srgb, var(--ground) 90%, transparent) 62%, transparent);
  opacity: 0; transition: opacity var(--base);
}
html[data-scrolled] #topbar::before { opacity: 1; }

