/* Home, the game page and a store page run their artwork under the strip.
   enhance.js marks the document once one of them is scrolled, and the page
   lays a ground under the strip so passing text does not collide with the
   search field. It belongs to the page, not to the strip: the game page and
   the store page keep their own Back buttons up there, inside their own
   stacking context, and a ground on the strip would cover them. */
#page-home::after, #game-flyout::after, #store-detail::after {
  content: ''; position: absolute; inset: 0 12px auto 0; height: calc(var(--top-h) + 26px); z-index: 25; pointer-events: none;
  background: linear-gradient(180deg, var(--ground) 0%, color-mix(in srgb, var(--ground) 90%, transparent) 62%, transparent);
  opacity: 0; transition: opacity var(--base);
}
html[data-scrolled] :is(#page-home, #game-flyout, #store-detail)::after { opacity: 1; }
